{
  "id": "a47d6af4-2f88-4926-8b28-3c3fa3f60114",
  "version": "1.9",
  "name": "VendorPOReview",
  "nodes": [
    {
      "id": "start",
      "type": "core.trigger.manual",
      "typeVersion": "1.0",
      "display": {
        "label": "Manual trigger"
      },
      "inputs": {
        "entryPointId": "823df6b2-e0ff-47a4-905f-cb257ca10c6c",
        "isDefaultEntryPoint": true
      }
    },
    {
      "id": "fetchPOData",
      "type": "core.action.script",
      "typeVersion": "1.1",
      "display": {
        "label": "Fetch PO Data"
      },
      "inputs": {
        "script": "return { poNumber: 'PO-2026-00142', vendorName: 'Acme Supplies Inc.', totalAmount: 47850.00 };"
      }
    },
    {
      "id": "poReview",
      "type": "uipath.human-in-the-loop.quick-form",
      "typeVersion": "1.0",
      "display": {
        "label": "PO Review"
      },
      "inputs": {
        "schema": {
          "schemaId": "b2f3e1a4-9c8d-4e7f-a5b6-c3d2e1f08765",
          "fields": [
            {
              "id": "poNumber",
              "label": "PO Number",
              "type": "text",
              "direction": "input",
              "binding": "vars.fetchPOData.output.poNumber"
            },
            {
              "id": "vendorName",
              "label": "Vendor Name",
              "type": "text",
              "direction": "input",
              "binding": "vars.fetchPOData.output.vendorName"
            },
            {
              "id": "totalAmount",
              "label": "Total Amount",
              "type": "number",
              "direction": "input",
              "binding": "vars.fetchPOData.output.totalAmount"
            },
            {
              "id": "notes",
              "label": "Notes",
              "type": "text",
              "direction": "output",
              "variable": "vars.reviewNotes"
            }
          ],
          "outcomes": [
            {
              "id": "approve",
              "name": "Approve",
              "type": "string",
              "isPrimary": true,
              "action": "Continue"
            },
            {
              "id": "reject",
              "name": "Reject",
              "type": "string",
              "isPrimary": false,
              "action": "End"
            }
          ]
        },
        "recipient": {
          "channels": [
            "Email",
            "ActionCenter"
          ],
          "connections": {},
          "assignee": {
            "type": "group"
          }
        },
        "priority": "High"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "Task result data",
          "source": "=result",
          "var": "output",
          "properties": {
            "notes": {
              "type": "string"
            },
            "Action": {
              "type": "string",
              "enum": ["Approve", "Reject"],
              "default": "Approve"
            }
          }
        },
        "status": {
          "type": "string",
          "description": "Task completion status",
          "source": "=result.Action",
          "var": "status",
          "enum": ["Approve", "Reject"],
          "default": "Approve"
        }
      }
    },
    {
      "id": "routeDecision",
      "type": "core.logic.decision",
      "typeVersion": "1.2",
      "display": {
        "label": "Approved?"
      },
      "inputs": {
        "expression": "$vars.poReview.status === \"Approve\"",
        "trueLabel": "Approved",
        "falseLabel": "Rejected"
      }
    },
    {
      "id": "logApproved",
      "type": "core.action.script",
      "typeVersion": "1.1",
      "display": {
        "label": "Log PO Approved"
      },
      "inputs": {
        "script": "return { message: 'PO approved' };"
      }
    },
    {
      "id": "endApproved",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": {
        "label": "End"
      }
    },
    {
      "id": "endRejected",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": {
        "label": "End (Rejected)"
      }
    }
  ],
  "edges": [
    {
      "id": "edge_start_output_fetchPOData_input",
      "sourceNodeId": "start",
      "sourcePort": "output",
      "targetNodeId": "fetchPOData",
      "targetPort": "input"
    },
    {
      "id": "edge_fetchPOData_success_poReview_input",
      "sourceNodeId": "fetchPOData",
      "sourcePort": "success",
      "targetNodeId": "poReview",
      "targetPort": "input"
    },
    {
      "id": "edge_poReview_completed_routeDecision_input",
      "sourceNodeId": "poReview",
      "sourcePort": "completed",
      "targetNodeId": "routeDecision",
      "targetPort": "input"
    },
    {
      "id": "edge_routeDecision_true_logApproved_input",
      "sourceNodeId": "routeDecision",
      "sourcePort": "true",
      "targetNodeId": "logApproved",
      "targetPort": "input"
    },
    {
      "id": "edge_logApproved_success_endApproved_input",
      "sourceNodeId": "logApproved",
      "sourcePort": "success",
      "targetNodeId": "endApproved",
      "targetPort": "input"
    },
    {
      "id": "edge_routeDecision_false_endRejected_input",
      "sourceNodeId": "routeDecision",
      "sourcePort": "false",
      "targetNodeId": "endRejected",
      "targetPort": "input"
    }
  ],
  "definitions": [
    {
